CREATE FUNCTION "enforce_student_challenge_progress"() RETURNS trigger AS $$
DECLARE challenge_target INTEGER;
BEGIN
  SELECT "target" INTO challenge_target FROM "StudentGroupChallenge" WHERE "id" = NEW."challengeId" FOR SHARE;
  IF challenge_target IS NULL OR NEW."progress" < 0 OR NEW."progress" > challenge_target THEN
    RAISE EXCEPTION 'challenge progress must be between zero and the canonical target';
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;
CREATE TRIGGER "StudentGroupChallengeParticipant_progress_target_trigger" BEFORE INSERT OR UPDATE OF "progress", "challengeId" ON "StudentGroupChallengeParticipant" FOR EACH ROW EXECUTE FUNCTION "enforce_student_challenge_progress"();
